// Called only by authenticated Node dispatch once consent + OTP are persisted.
// The flags are informational defense-in-depth; the future Node authorization
// handler must validate them against durable quote/OTP state before dispatch.
const b = $input.first().json.body ?? {};
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if(b.agentKey!=='ancfz'||b.otpVerified!==true||b.customerConsent!==true) throw new Error('ANCFZ approval missing');
if(typeof b.ticketId!=='string'||!uuid.test(b.ticketId)) throw new Error('Invalid ticket ID');
if(typeof b.quotationId!=='string'||!uuid.test(b.quotationId)) throw new Error('Invalid quotation ID');
if(typeof b.externalReference!=='string'||!/^ANCFZ-[A-Za-z0-9_-]{8,160}$/.test(b.externalReference)) throw new Error('Invalid stable external reference');
if(b.currency!=='AED') throw new Error('ANCFZ quotations must be in AED; verify the sandbox supports AED before enabling');
if(typeof b.amount!=='string'||! /^(?:0|[1-9]\d{0,7})\.\d{2}$/.test(b.amount)|| Number(b.amount)<=0) throw new Error('Expected approved decimal amount, e.g. 10.00');
if(typeof b.firstName!=='string'||!b.firstName.trim()||b.firstName.length>100) throw new Error('Invalid billing first name');
if(typeof b.email!=='string'||b.email.length>254||!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(b.email)) throw new Error('Invalid billing email');
if(typeof b.countryCode!=='string'||!/^[A-Z]{2}$/.test(b.countryCode)) throw new Error('Invalid country code');
return [{json:{agentKey:'ancfz',ticketId:b.ticketId,quotationId:b.quotationId,externalReference:b.externalReference,currency:'AED',amount:b.amount,firstName:b.firstName.trim(),email:b.email.trim(),countryCode:b.countryCode}}];

// 2Checkout mock REST/6.0 Orders. An order creation response is NEVER proof of payment.
const r = $input.first().json;
if (!r || typeof r !== 'object' || Array.isArray(r)) throw Error('Invalid 2Checkout order response');
const e = $('Validate Authorized Payment').first().json;
const ref = r.RefNo ?? r.OrderNo ?? r.order_number;
if (typeof ref !== 'string' || !/^[A-Za-z0-9_-]{1,120}$/.test(ref))
  throw Error('Missing valid 2Checkout order reference');
if (r.ExternalReference !== e.externalReference) {
  // Never log real provider/order values, PII or credentials. Classify the
  // failing mock template so an HTTP 500 is actionable without trusting it.
  const kind = r.ExternalReference == null ? 'missing' :
    typeof r.ExternalReference !== 'string' ? 'wrong_type' :
    /^\\{\\{[A-Za-z0-9_.-]+\\}\\}$/.test(r.ExternalReference) ?
      'unexpanded_template' : 'different_value';
  throw Error('2Checkout external reference mismatch (' + kind + ')');
}
if (r.Currency !== e.currency) throw Error('2Checkout currency mismatch');
if (typeof r.GrossPrice !== 'string' || !/^\d{1,9}\.\d{2}$/.test(r.GrossPrice) || r.GrossPrice !== e.amount)
  throw Error('2Checkout gross amount mismatch');
const urlText = r.redirect_url ?? r.PaymentDetails?.PaymentMethod?.RedirectURL ?? null;
let checkoutUrl = null;
if (urlText !== null) {
  if (typeof urlText !== 'string' || urlText.length > 2048) throw Error('Invalid checkout URL');
  // n8n 2.x Code nodes do not expose the URL global. Match only the
  // provider's HTTPS hosted checkout path, with no credentials/query/fragment.
  if (!/^https:\/\/mockgateway\.com\/pg\/pay\/[A-Za-z0-9_-]{1,160}$/.test(urlText))
    throw Error('Untrusted 2Checkout redirect URL');
  checkoutUrl = urlText;
}
const providerPaymentId=checkoutUrl
  ? /^https:\/\/mockgateway\.com\/pg\/pay\/([A-Za-z0-9_-]{1,120})$/.exec(checkoutUrl)?.[1]??null
  : null;
if(checkoutUrl&&!providerPaymentId)throw Error('Missing provider payment identifier');
return [{json:{
  status:checkoutUrl ? 'checkout_available' : 'order_created_checkout_unavailable',
  verified:false, provider:'2checkout_mock', orderReference:ref,providerPaymentId,
  externalReference:e.externalReference, ticketId:e.ticketId, quotationId:e.quotationId,
  amount:e.amount, currency:e.currency, checkoutUrl,
}}];
